export interface CompleteTopicNote {
  explanation: string;
  keyPoints: string[];
  vocabulary: { term: string; definition: string }[];
  funFact: string;
  recap: string;
}

export interface CompleteTopicDef {
  title: string;
  description: string;
  order: number;
  isFreeSample?: boolean;
  note: CompleteTopicNote;
  quizQuestions: {
    question: string;
    options: { A: string; B: string; C: string; D: string };
    correct: 'A' | 'B' | 'C' | 'D';
    explanation: string;
    imagePrompt?: string;
  }[];
}

type QuizQ = CompleteTopicDef['quizQuestions'][number];

function q(
  question: string,
  A: string,
  B: string,
  C: string,
  D: string,
  correct: 'A' | 'B' | 'C' | 'D',
  explanation: string,
  imagePrompt?: string
): QuizQ {
  return { question, options: { A, B, C, D }, correct, explanation, imagePrompt };
}

